def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    mark = next(x for x in set(v for row in grid for v in row) if x != bg)
    out = [row[:] for row in grid]
    # Bridge gaps between marker cells in each row and column using color 3.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        if cs:
            for c in range(min(cs), max(cs) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        if rs:
            for r in range(min(rs), max(rs) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    return out

